"use strict";const fs=require("fs");const path=require("path");const REVIEWS_DIR="/Users/younghwankang/WORK/WORKSPACE/KiiPS/.claude/gemini-bridge/reviews";const ACKS_FILE="/Users/younghwankang/WORK/WORKSPACE/KiiPS/.claude/gemini-bridge/.review-acks.json";const REVIEW_TTL_MS=24*60*60*1e3;const MAX_REVIEWS_TO_SCAN=30;function loadAcks(){try{if(!fs.existsSync(ACKS_FILE)){return{}}const raw=fs.readFileSync(ACKS_FILE,"utf8");return JSON.parse(raw)}catch(_e){return{}}}function checkGeminiReviews(filePath){if(!filePath)return null;if(!fs.existsSync(REVIEWS_DIR))return null;const acks=loadAcks();const targetBasename=path.basename(filePath);const now=Date.now();let reviewFiles;try{reviewFiles=fs.readdirSync(REVIEWS_DIR).filter(f=>f.endsWith(".json")).sort().reverse().slice(0,MAX_REVIEWS_TO_SCAN)}catch(_e){return null}for(const filename of reviewFiles){let review;try{const raw=fs.readFileSync(path.join(REVIEWS_DIR,filename),"utf8");review=JSON.parse(raw)}catch(_e){continue}if(review.status!=="completed")continue;if(!review.needsAttention)continue;const reviewId=review.id||filename.replace(".json","");if(acks[reviewId])continue;if(review.createdAt){const reviewAge=now-new Date(review.createdAt).getTime();if(reviewAge>REVIEW_TTL_MS)continue}const reviewFiles_=Array.isArray(review.files)?review.files:[];const matchesFile=reviewFiles_.some(f=>path.basename(f)===targetBasename);if(!matchesFile)continue;const criticalIssues=(review.issues||[]).filter(issue=>issue.severity==="critical");if(criticalIssues.length>0){return{reviewId:reviewId,issues:criticalIssues}}}return null}function formatBlockMessage(basename,reviewId,issues){const issueLines=issues.map(i=>`  - ${i.text}`).join("\n");return`\n`+`╔══════════════════════════════════════════════════════╗\n`+`║  GEMINI REVIEW GATE - Unresolved Critical Issues     ║\n`+`╚══════════════════════════════════════════════════════╝\n`+`\n`+`File: ${basename}\n`+`Review: ${reviewId}\n`+`\n`+`Critical issues:\n`+`${issueLines}\n`+`\n`+`Resolve these issues first, or acknowledge with:\n`+`  "I have reviewed the Gemini findings for ${reviewId}"\n`+`\n`+`To acknowledge all: /gemini-handoff read\n`}if(require.main===module){const safetyTimer=setTimeout(()=>{process.stderr.write("[GeminiReviewGate] stdin timeout - allowing\n");process.exit(0)},5e3);const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",chunk=>chunks.push(chunk));process.stdin.on("end",()=>{clearTimeout(safetyTimer);try{const input=chunks.join("");if(!input.trim()){process.exit(0)}const event=JSON.parse(input);const toolName=(event.tool_name||"").toLowerCase();if(toolName!=="edit"&&toolName!=="write"){process.exit(0)}const filePath=(event.tool_input||{}).file_path||"";if(!filePath){process.exit(0)}const result=checkGeminiReviews(filePath);if(result){const basename=path.basename(filePath);process.stderr.write(formatBlockMessage(basename,result.reviewId,result.issues));process.exit(2)}process.exit(0)}catch(_e){process.exit(0)}});process.stdin.resume()}module.exports={checkGeminiReviews:checkGeminiReviews,loadAcks:loadAcks};